  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PARTIAL",
      "chunk_id": "text_5",
      "quote": "Studies were included based on the following criteria: (1) a randomized controlled trial (RCT) design; (2) the presence of both an exercise intervention group and a control group; (3) participants had been diagnosed with stroke; and (4) depression was assessed as the primary outcome.",
      "reason": "Design, population, comparison, and outcome criteria are specified, but no setting or follow-up requirements are reported."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PARTIAL",
      "chunk_id": "text_5",
      "quote": "Studies were excluded if they met any of the following conditions: (1) published in languages other than English; (2) review articles and conference abstracts;",
      "reason": "Language restriction and publication/report status (reviews, conference abstracts excluded) are specified, but no dissemination year range is stated as an eligibility criterion."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "PARTIAL",
      "chunk_id": "text_9",
      "quote": "resulting in the exclusion of 14 articles due to the following reasons: (1) inability to extract data ( n = 9); (2) lack of outcome measures ( n = 2); and (3) non-exercise interventions ( n = 3).",
      "reason": "Full-text screening reasons distinguish 'lack of outcome measures' from 'inability to extract data', but the eligibility criteria (text_5) only mention exclusion for outcomes not quantifiable as mean and SD, without explicitly distinguishing outcomes not measured from results not reported."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PARTIAL",
      "chunk_id": "text_10",
      "quote": "In terms of intervention types, 10 studies [24,25,37,38,40,42-45,51] incorporated aerobic exercise; 2 studies [39,52] implemented resistance exercise; 10 studies [23,26,43,46-48,50,53-55] employed multicomponent training... 2 studies [24,49] utilized high-intensity interval training (HIIT)",
      "reason": "Synthesis groups by intervention type (aerobic, resistance, multicomponent, HIIT) versus control are evident from the results, but the grouping is not specified in the eligibility criteria/methods nor explicitly linked to the review objectives' comparisons."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No rationale is provided for notable eligibility restrictions such as the English-language limit or exclusion of high risk of bias studies."
    }
